   */
  def check_concrete_output(cycle_frame: EIT_Acquisition_Supervisor.CycleFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val cycle_frameValue: EIT_Acquisition_Supervisor.CycleFrame = get_cycle_frame().get
